"""Dynamic radius footprint and depth-layer preview for native sculpt brush."""
import hashlib
import json

PREVIEW_JS = "function atelierSculptPickMarkerRefresh(){\n atelierSculptPickMarkerClear();\n if(!atelierSculptPickLabel)atelierSculptPickLabel=document.getElementById('modelAtelierSculptPickedReadout');\n const hit=atelierSculptHit;\n if(atelierSculptPickLabel)atelierSculptPickLabel.hidden=!hit;\n if(!hit||!modelRoot||!world)return;\n const part=partById(hit.partId);\n const mesh=modelRoot.children.find(o=>o.isMesh&&o.userData.atelierId===hit.partId);\n if(!part||!mesh)return;\n mesh.updateMatrixWorld(true);\n // Use the actual form (including screen-pixel radius conversions, rotations,\n // negative intrude strength and selection limits), not a fixed ring size.\n const form=atelierSculptForm();\n const hasForm=!!form&&Number.isFinite(form.radius)&&form.radius>0&&\n   form.center.every(Number.isFinite)&&form.axis.every(Number.isFinite);\n const centerLocal=new THREE.Vector3(...(hasForm?form.center:hit.center));\n const normalLocal=new THREE.Vector3(...(hasForm?form.axis:hit.axis)).normalize();\n const axisLocal=normalLocal.clone();\n if(hasForm)axisLocal.applyEuler(new THREE.Euler(form.pitch,form.yaw,0,'YXZ')).normalize();\n // Fallback if inputs are between edits. Never use invalid unbounded values.\n const radius=hasForm?form.radius:.055;\n const signedDepth=hasForm&&form.operation==='push'?form.strength:0;\n const helper=new THREE.Group();\n helper.name='Picked sculpt center indicator (editor only)';\n helper.userData.atelierHelper=true;\n const centerWorld=mesh.localToWorld(centerLocal.clone());\n helper.position.copy(centerWorld);\n const axisWorld=axisLocal.clone().applyMatrix3(\n   new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld)).normalize();\n const crossA=new THREE.Vector3(0,1,0);\n if(Math.abs(crossA.dot(axisLocal))>.9)crossA.set(1,0,0);\n const tangentU=new THREE.Vector3().crossVectors(axisLocal,crossA).normalize();\n const tangentV=new THREE.Vector3().crossVectors(axisLocal,tangentU).normalize();\n const segments=48;\n function lineLoop(localRadius,offset,color,opacity,order){\n  const points=[];\n  for(let i=0;i<segments;i++){\n   const a=2*Math.PI*i/segments;\n   const local=centerLocal.clone().addScaledVector(axisLocal,offset)\n    .addScaledVector(tangentU,Math.cos(a)*localRadius)\n    .addScaledVector(tangentV,Math.sin(a)*localRadius);\n   points.push(mesh.localToWorld(local).sub(centerWorld));\n  }\n  const geometry=new THREE.BufferGeometry().setFromPoints(points);\n  const material=new THREE.LineBasicMaterial({\n   color,transparent:true,opacity,depthTest:false,depthWrite:false\n  });\n  const ring=new THREE.LineLoop(geometry,material);\n  ring.renderOrder=order;helper.add(ring);\n  return points;\n }\n // Amber = exact chosen LOCAL brush radius in the tangent plane. This is a\n // footprint guide, not a promise about affected topology or occlusion.\n const footprint=lineLoop(radius,0,0xffdc69,.98,990);\n const centerPoint=new THREE.Vector3();\n const tipWorld=mesh.localToWorld(centerLocal.clone().addScaledVector(axisLocal,signedDepth)).sub(centerWorld);\n // White crosshair remains small and readable at large influence radii.\n const crossRadius=Math.max(.018,Math.min(.045,radius*.22));\n const crossVertices=[];\n for(const dir of [tangentU,tangentV]){\n  for(const sign of [-1,1]){\n   const pt=mesh.localToWorld(centerLocal.clone().addScaledVector(dir,sign*crossRadius)).sub(centerWorld);\n   crossVertices.push(pt);\n  }\n }\n const cross=new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(crossVertices),\n  new THREE.LineBasicMaterial({color:0xffffff,depthTest:false,depthWrite:false}));\n cross.renderOrder=991;helper.add(cross);\n const depthRadius=Math.min(radius*.24,Math.max(.02,radius*.12));\n if(Math.abs(signedDepth)>0.00001){\n  // Violet inset plane and tapered spokes illustrate the displacement at the\n  // center. Surface edges have falloff and DO NOT all travel full depth.\n  const depthRing=lineLoop(depthRadius,signedDepth,0xbf93ff,.95,992);\n  const spokes=[];\n  for(let i=0;i<segments;i+=6)spokes.push(footprint[i].clone(),depthRing[i].clone());\n  const walls=new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(spokes),\n   new THREE.LineBasicMaterial({color:0xbf93ff,transparent:true,opacity:.43,\n    depthTest:false,depthWrite:false}));\n  walls.renderOrder=990;helper.add(walls);\n  const depthLine=new THREE.Line(new THREE.BufferGeometry().setFromPoints([centerPoint,tipWorld]),\n   new THREE.LineBasicMaterial({color:0x61f2e6,depthTest:false,depthWrite:false}));\n  depthLine.renderOrder=993;helper.add(depthLine);\n }\n const arrowLength=Math.max(.075,Math.min(.16,radius*.5));\n const arrow=new THREE.ArrowHelper(axisWorld,new THREE.Vector3(0,0,0),\n  arrowLength,0x61f2e6,Math.min(.04,arrowLength*.3),Math.min(.025,arrowLength*.2));\n arrow.traverse(o=>{\n  if(o.material){o.material.depthTest=false;o.material.depthWrite=false;}\n  o.renderOrder=994;\n });helper.add(arrow);\n world.add(helper);\n atelierSculptPickIndicator=helper;\n atelierHDDirty=true;\n if(atelierSculptPickLabel){\n  const coords=centerLocal.toArray().map(v=>v.toFixed(3)).join(', ');\n  const depthLabel=hasForm?Math.abs(signedDepth).toFixed(3):'—';\n  atelierSculptPickLabel.textContent=\n    '● Pick: ('+coords+') · amber radius '+radius.toFixed(3)+\n    ' · violet center-depth '+depthLabel+\n    ' ('+(signedDepth<0?'inward':signedDepth>0?'outward':'no push')+\n    ') · cyan axis · preview only; Apply brush commits';\n }\n}\nfunction atelierSculptPreviewFieldsInstall(){\n const ids=new Set([\n  'modelAtelierSculptBrushRadius','modelAtelierSculptBrushRadiusUnits',\n  'modelAtelierSculptBrushRadiusScreen','modelAtelierSculptBrushAmount',\n  'modelAtelierSculptBrushMode','modelAtelierSculptBrushYaw',\n  'modelAtelierSculptBrushPitch','modelAtelierSculptBrushFalloff',\n  'modelAtelierSculptBrushPlateau','modelAtelierSculptBrushTaper',\n  'modelAtelierSculptBrushCenter0','modelAtelierSculptBrushCenter1',\n  'modelAtelierSculptBrushCenter2','modelAtelierSculptBrushAxis0',\n  'modelAtelierSculptBrushAxis1','modelAtelierSculptBrushAxis2'\n ]);\n const update=e=>{\n  if(!ids.has(e.target?.id)||!atelierSculptHit)return;\n  atelierSculptPickMarkerRefresh();\n };\n document.addEventListener('input',update,true);\n document.addEventListener('change',update,true);\n}\n"

def once(s,a,b):
    count=s.count(a)
    assert count==1,(a[:100],count)
    return s.replace(a,b,1)

def apply(html):
    start=html.index('function atelierSculptPickMarkerRefresh(){')
    end=html.index('\n}\nlet atelierSculptArmed=false,atelierSculptHit=null;',start)+2
    assert html.count('function atelierSculptPickMarkerRefresh(){')==1
    assert 'const radius=.055;' in html[start:end]
    html=html[:start]+PREVIEW_JS+html[end:]
    html=once(html,
       ' atelierSculptPickMarkerInstall();\n $m(\'SculptBrushPick\').addEventListener',
       ' atelierSculptPickMarkerInstall();\n atelierSculptPreviewFieldsInstall();\n $m(\'SculptBrushPick\').addEventListener')
    html=once(html,
      'SWYRL_ENGINE_DEPLOY_MARKER: V11_106_SCULPT_RENDER_MODE_REBUILD',
      'SWYRL_ENGINE_DEPLOY_MARKER: V11_107_RADIUS_DEPTH_PREVIEW')
    for a,b in [
     ('ENGINE · MAKER v11.106','ENGINE · MAKER v11.107'),
     ('v11.106 · stable viewport mode after sculpt','v11.107 · live radius and depth brush preview'),
     ("window.SWRLZ_FORGE_BUILD={version:'v11.106'","window.SWRLZ_FORGE_BUILD={version:'v11.107'"),
     ('<title>§wyrl§ Engine · Maker v11.106</title>','<title>§wyrl§ Engine · Maker v11.107</title>')
    ]:html=once(html,a,b)
    key='const SE_RELEASE_NOTES=';at=html.index(key)+len(key)
    notes,n=json.JSONDecoder().raw_decode(html[at:])
    notes.update(title='Live brush radius ring and center depth guide before applying',
      date='2026-10-24',changes=[
       'Picked center guide now reflects the exact local brush radius (or converted screen-pixel radius) instead of a constant marker size.',
       'Show a violet inset ghost depth layer, tapered spokes and displacement axis for the selected intrude/extrude amount before Apply brush.',
       'Update visual guides whenever brush radius, depth, action, yaw/pitch or center fields change, including from the custom mobile keypad.',
       'Editor-only guides never save or deform mesh geometry and preserve viewport rendering, menus, touch input, Undo and exports.'
      ])
    html=html[:at]+json.dumps(notes,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+html[at+n:]
    raw=html.encode('utf-8')
    print('SWRLZ_V11107_BUILD_MEASURE',len(raw),hashlib.sha256(raw).hexdigest(),flush=True)
    return html
